[
  {
    "statement": "Setting and enforcing vessel speed limits is the most evidence-based method for reducing lethal vessel strikes on large whales.",
    "citations": []
  },
  {
    "statement": "A study in the North Atlantic Ocean found that setting vessel speed limits during specific periods in key habitats resulted in fewer North Atlantic right whale deaths caused by collisions.",
    "citations": []
  },
  {
    "statement": "A study in the Indian River estuarine system found fewer manatee deaths after speed limits were set and enforced in all areas.",
    "citations": []
  },
  {
    "statement": "Methods such as diverting shipping routes, modifying vessels, using observers, or remote detection tools have been proposed to reduce whale strikes.",
    "citations": []
  },
  {
    "statement": "No studies have evaluated the effectiveness of diverting shipping routes, modifying vessels, using observers, or remote detection tools for whale strike reduction.",
    "citations": []
  }
]

[
  {
    "statement": "No studies were found that evaluated public education campaigns specifically aimed at reducing plastic litter ingestion by river dolphins in South America.",
    "citations": []
  },
  {
    "statement": "The search revealed limited research on public education campaigns targeting plastic pollution affecting marine and freshwater mammals.",
    "citations": []
  },
  {
    "statement": "A study in the Sundarbans mangroves in Bangladesh found that an educational exhibition improved participants' willingness to change behavior to support marine conservation.",
    "citations": []
  },
  {
    "statement": "The educational exhibition in the Sundarbans mangroves was not specific to plastic pollution or river dolphins.",
    "citations": []
  },
  {
    "statement": "Several studies examined marine mammal education campaigns more broadly.",
    "citations": []
  },
  {
    "statement": "Three before-and-after studies found that educational whale-watching tours and exhibitions improved participants' willingness to support marine conservation.",
    "citations": []
  },
  {
    "statement": "Three before-and-after studies found that educational whale-watching tours and exhibitions improved participants' willingness to donate money or cut fishing nets to save dolphins.",
    "citations": []
  },
  {
    "statement": "The educational whale-watching tours and exhibitions did not specifically address plastic litter ingestion by river dolphins in South America.",
    "citations": []
  }
]
